// Wertet die Entscheidung von der Gate-2-Seite aus (BC3-81 weckt BC3-00, das gibt antwort, pruefung und umschlag weiter).
// Drei Entscheidungen: freigeben (Pull Request an BC4), nachbessern, ablehnen.
// Eine Freigabe trotz offener maschineller Punkte wird vermerkt, nicht verhindert.
const rein = $input.first().json;
const antwort = rein.antwort || {};
const pruefung = rein.pruefung || {};
const u = rein.umschlag || {};

const wahl = String(antwort['Deine Entscheidung'] || '').toLowerCase().trim();
const freigegeben = wahl.startsWith('freigeben');
const nachbessern = wahl.startsWith('zurück') || wahl.startsWith('zurueck');
const entscheidung = freigegeben ? 'approved' : (nachbessern ? 'nachbessern' : 'rejected');
// Nach 7 Tagen ohne Antwort gibt BC3-00 das Item ohne Antwortfelder weiter
const fristAbgelaufen = antwort['Deine Entscheidung'] === undefined;
const FRIST_GRUND = 'Frist abgelaufen: keine Antwort an Gate 2 innerhalb von 7 Tagen, als Ablehnung gewertet';

const maschinell = pruefung.bestaetigt || [];
const offenGeblieben = pruefung.offen || [];

const KRITERIEN = 'Die Akzeptanzkriterien — siehst du das auch so?';
const AUFSICHT = 'Die menschliche Aufsicht — siehst du das auch so?';
const kriterienUrteil = String(antwort[KRITERIEN] || '').trim();
const aufsichtUrteil = String(antwort[AUFSICHT] || '').trim();
const anmerkung = String(antwort['Deine Anmerkung'] || '').trim();
const stichprobe = kriterienUrteil;

// Ein Urteil zählt nur als bestätigt, wenn es positiv ist
const beurteilt = [
  stichprobe ? 'akzeptanzkriterien_guete' : null,
  aufsichtUrteil.toLowerCase().startsWith('ja') ? 'aufsicht_spezifiziert' : null,
].filter(Boolean);

const negativ = aufsichtUrteil.toLowerCase().startsWith('nein')
  ? [`${AUFSICHT}: ${aufsichtUrteil}`] : [];
const pruefpunkte = [...maschinell, ...beurteilt];

const trotzBefund = freigegeben ? offenGeblieben : [];

const befunde = [];
if (fristAbgelaufen) {
  befunde.push(FRIST_GRUND + '. Niemand hat die Lieferung angesehen. Es entsteht '
    + 'kein Pull Request; für eine Lieferung neu starten.');
} else if (!stichprobe) {
  befunde.push('Zu den Akzeptanzkriterien liegt kein Urteil vor. BC3 hatte '
    + 'seine Einschätzung vorgelegt; ohne Zustimmung oder Widerspruch ist '
    + 'unbelegt, dass sie überhaupt angesehen wurde.');
} else if (kriterienUrteil.toLowerCase().startsWith('das kann ich')) {
  befunde.push('Die freigebende Person konnte die Akzeptanzkriterien auf der Gate-2-Seite '
    + 'nicht beurteilen. Der Seite fehlt etwas, das sie zum Urteil bräuchte.');
} else if (kriterienUrteil.toLowerCase().startsWith('nein')) {
  befunde.push(`Widerspruch zur Einschätzung von BC3: "${kriterienUrteil}". `
    + (anmerkung ? `Begründung: ${anmerkung}` : 'Ohne weitere Angabe.')
    + ' BC3 hielt Nummer ' + (pruefung.stichprobe_schwaechstes ?? '-')
    + ' für das schwächste.');
}
if (negativ.length) {
  befunde.push('Ausdrückliche Vorbehalte der freigebenden Person: '
    + negativ.join('; ') + '. Diese Punkte gelten NICHT als bestätigt.');
}
if (offenGeblieben.length) {
  const namen = (pruefung.geprueft || [])
    .filter(g => offenGeblieben.includes(g.id))
    .map(g => `${g.titel} (${g.beleg})`);
  befunde.push(`Maschinell nicht bestätigt: ${namen.join('; ')}.`);
}
if (trotzBefund.length) {
  befunde.push(`Freigegeben trotz ${trotzBefund.length} offener Prüfpunkte: `
    + `${trotzBefund.join(', ')}. Begründung: `
    + `${anmerkung || 'ohne Angabe'}.`);
}
if (nachbessern) {
  befunde.push('Zur Nachbesserung zurückgegeben: '
    + (anmerkung || 'ohne Angabe')
    + ' Es entsteht kein Pull Request; die Dateien bleiben im Lieferungsordner.');
}
if (!freigegeben && !nachbessern && !fristAbgelaufen) {
  befunde.push('Lieferung abgelehnt: ' + (anmerkung || 'ohne Angabe'));
}
// Bei Hochrisiko ist eine fehlende Antwort zur Aufsicht ein Befund (Feld bleibt optional)
if (pruefung.hochrisiko && !aufsichtUrteil && !fristAbgelaufen) {
  befunde.push('Hochrisiko nach Anhang III, aber kein Urteil zur menschlichen Aufsicht. '
    + 'Damit ist offen, ob die Tickets Übersteuern, Anhalten und Protokollieren abdecken '
    + '(Art. 14 Abs. 4 d und e, Art. 12). Vor der Übergabe an BC4 nachtragen oder die '
    + 'Lieferung zurückholen.');
}
if (pruefung.hochrisiko && aufsichtUrteil.toLowerCase().startsWith('nein')) {
  befunde.push('Hochrisiko nach Anhang III, und die menschliche Aufsicht ist laut '
    + 'freigebender Person nicht ausreichend beschrieben (Art. 14). Vor der Übergabe '
    + 'an BC4 nachtragen.');
}

const dateien = (u.lieferung?.dateien || []).map(d =>
  d._datei === 'tickets'
    ? { ...d, gate2: { status: entscheidung } }
    : d
);

return [{
  json: {
    lauf_id: rein.lauf_id,
    entscheidung,
    ereignis: {
      gate: 2,
      objekt_typ: 'lieferung',
      objekt_id: rein.lauf_id,
      ereignis: freigegeben ? 'freigabe' : (nachbessern ? 'nachbesserung' : 'ablehnung'),
      benutzer: antwort['Wer gibt frei'] || (fristAbgelaufen ? 'niemand (Frist abgelaufen)' : null),
      frist_abgelaufen: fristAbgelaufen,
      am: new Date().toISOString(),
      grundlage: u.quelle?.url || null,
      grund: anmerkung || (fristAbgelaufen ? FRIST_GRUND : null),
      pruefpunkte,
      maschinell_bestaetigt: maschinell,
      maschinell_offen: offenGeblieben,
      freigabe_trotz_befund: trotzBefund,
      guete: {
        akzeptanzkriterien: stichprobe || null,
        stichprobe_antwort: kriterienUrteil || null,
        anmerkung: anmerkung || null,
        bc3_hielt_fuer_schwaechstes: pruefung.stichprobe_schwaechstes ?? null,
        stichprobe_gezeigt: (pruefung.stichprobe || []).map(k => k.text),
        aufsicht: aufsichtUrteil || null,
      },
    },
    umschlag: {
      ...u,
      // ...u.lieferung erhalten, dort stehen die Dateikennungen aus BC3-70
      lieferung: { ...(u.lieferung || {}), dateien },
      gate2: {
        entscheidung,
        stand: pruefung.stand || null,
        maschinell_offen: offenGeblieben,
      },
      protokoll: [...(u.protokoll || []), {
        stufe: 'BC3-80 Gate 2',
        zeitpunkt: new Date().toISOString(),
        status: freigegeben ? 'freigegeben' : (nachbessern ? 'nachbessern' : 'abgelehnt'),
        umfang: pruefung.stand || null,
        befunde,
      }],
    },
  },
}];

// Baut die Lieferung für contracts/bc3-to-bc4/<projekt>/<lieferung_id>/ zusammen, legt noch nichts an.
// Ein Ordner je Lieferung (seit 23.10.2026), damit Lieferungen zum selben Kernprozess sich nicht überschreiben.
// Nach der Freigabe an Gate 2 führt BC3 selbst zusammen, BC4 holt aus main.
const REPO = 'pg-coe-kmu/coe-factory';
const BASIS = 'contracts/bc3-to-bc4';
const AUS_ZWEIG = 'main';

// offene-punkte.json bleibt in _vorschau, sie ist die Akte von BC3
const PFADE = {
  tickets: 'ticket_set.json',
  blueprint: 'blueprint.json',
  architecture: 'architecture.md',
  'compliance-audit': 'compliance-audit.json',
};

const g = $input.first().json;
const u = g.umschlag || {};
const lieferung = u.lieferung || {};
const id = lieferung.lieferung_id;
const projekt = lieferung.projekt_kurzname;

if (g.entscheidung !== 'approved') {
  throw new Error('Läuft nur im Freigabe-Zweig, die Verzweigung davor ist falsch verbunden (BC3-80 Lieferung ins Repo vorbereiten)');
}
if (!id || !projekt) {
  throw new Error('Im Umschlag fehlt lieferung_id oder projekt_kurzname (BC3-80). Lief BC3-40 durch?');
}

const zweig = `lieferung/${id}`;

// Wächter: das Token darf im ganzen Repository schreiben
if (!/^lieferung\/[A-Za-z0-9._-]+$/.test(zweig)) {
  throw new Error(`Der Zweigname "${zweig}" passt nicht auf lieferung/<kennung>. Abbruch.`);
}
if (zweig === AUS_ZWEIG || /^(main|master)$/i.test(zweig)) {
  throw new Error('Es wird niemals auf den Hauptzweig geschrieben. Abbruch.');
}

// --- Dateiinhalte ----------------------------------------------------------
const dateien = [];
for (const d of lieferung.dateien || []) {
  const ziel = PFADE[d._datei];
  if (!ziel) continue;                       // Unbekanntes bleibt draußen

  let text;
  if ((d._endung || 'json') === 'json') {
    const rein = {};
    for (const [k, v] of Object.entries(d)) if (!k.startsWith('_')) rein[k] = v;
    text = JSON.stringify(rein, null, 2);
  } else {
    text = String(d.inhalt ?? '');
  }
  if (!text) throw new Error(`Die Datei "${d._datei}" hat keinen Inhalt.`);

  const pfad = `${BASIS}/${projekt}/${id}/${ziel}`;
  if (!pfad.startsWith(BASIS + '/')) {
    throw new Error(`Der Pfad "${pfad}" liegt außerhalb von ${BASIS}. Abbruch.`);
  }
  if (pfad.includes('..')) {
    throw new Error(`Der Pfad "${pfad}" enthält "..". Abbruch.`);
  }

  dateien.push({
    pfad,
    inhalt: text,
    bytes: Buffer.byteLength(text, 'utf-8'),
    botschaft: `${d._datei} aus ${id}`,
  });
}

if (!dateien.length) {
  throw new Error('Keine lieferbare Datei im Umschlag gefunden.');
}

// --- Text des Pull Requests ------------------------------------------------
const t = (lieferung.dateien || []).find(x => x._datei === 'tickets') || {};
const anzahlStories = (t.epics || []).reduce((n, e) => n + (e.stories || []).length, 0);
const prot = u.protokoll || [];
const befunde = prot.flatMap(x => (x.befunde || []).map(b => `- **${x.stufe}:** ${b}`));
const e = g.ereignis || {};
// Seit 25.10.2026: Kennungen der Kette unverändert von BC2, BC4 nimmt sich, was es braucht (Simeon, ADR-003)
const k = u.ids || {};

const pr_text = [
  `Erzeugt von BC3, Lieferung \`${id}\`.`,
  '',
  '| | |',
  '|---|---|',
  `| Kernprozess | \`${t.konzept_ref?.kp_id || '?'}\` |`,
  `| Teilprozesse | ${(t.konzept_ref?.teilprozess_ids || []).join(', ') || '—'} |`,
  `| Quelle | \`${t.konzept_ref?.source_file || '?'}\` |`,
  `| Umfang | ${(t.epics || []).length} Epics, ${anzahlStories} Stories |`,
  `| Schema | \`${t.schema_version || '?'}\` |`,
  `| Herkunft der Zahlen | \`${t.konzept_ref?.value_quelle || 'nicht angegeben'}\` |`,
  `| Ordner | \`${BASIS}/${projekt}/${id}/\` |`,
  `| company_id | \`${k.company_id || '—'}\` |`,
  `| anfrage_id | \`${k.anfrage_id || '—'}\` |`,
  `| paket_id | \`${k.paket_id || '—'}\` |`,
  `| process_id | \`${k.process_id || '—'}\` |`,
  `| sub_process_id | \`${k.sub_process_id || '—'}\` |`,
  '',
  '## Gate 2',
  '',
  `Freigegeben von **${e.benutzer || 'unbekannt'}** am `
    + `${e.am || e.zeitpunkt || 'unbekannt'}.`,
  '',
  `Bestätigte Prüfpunkte: ${(e.pruefpunkte || []).join(', ') || 'keine genannt'}`,
  (e.grund || e.begruendung) ? `\nBegründung: ${e.grund || e.begruendung}` : '',
  '',
  ...((e.freigabe_trotz_befund || []).length
    ? ['> **Freigegeben trotz offener Prüfpunkte:** '
       + e.freigabe_trotz_befund.join(', ')
       + '. Die Begründung steht oben, die Abhilfe je Punkt im Protokoll unten.']
    : []),
  ...(e.guete
    ? ['Beurteilung durch die freigebende Person: '
       + [`Akzeptanzkriterien ${e.guete.akzeptanzkriterien || 'nicht beurteilt'}`,
          `Aufsicht ${e.guete.aufsicht || 'nicht beurteilt'}`].join(', ') + '.']
    : []),
  '',
  // Offene Punkte bleiben in der Akte von BC3, hier nur die Zahl
  ...(u.offene_punkte?.anzahl
    ? [`_BC3-intern: ${u.offene_punkte.anzahl} offene Punkte in `
       + '`offene-punkte.json` (liegt bei BC3 in `_vorschau`, nicht in dieser Lieferung): '
       + Object.entries(u.offene_punkte.nach_adressat || {})
           .map(([a, n]) => `${n} an ${a}`).join(', ') + '._',
       '']
    : []),
  '## Befunde aus dem Lauf',
  '',
  befunde.length ? befunde.join('\n') : '_keine_',
  '',
  '---',
  '',
  'Zum Prüfen: `ticket_set.json` gegen `tickets.schema.json` validieren.',
  '`compliance-audit.json` gehört nicht in den Generator. Zwei Angaben daraus '
    + 'braucht BC4 trotzdem: `empfohlene_zusatz_stories[].begruendung_pflicht_id` '
    + 'sagt, welche Story welche Pflicht erfüllt, und `pflichten_nach_adressat` '
    + 'sagt, welche Pflichten NICHT von BC4 gebaut werden.',
  '',
  'Freigegeben an Gate 2. BC3 führt die Lieferung selbst zusammen, BC4 holt sie aus `main`.',
].filter(x => x !== '').join('\n');

return [{
  json: {
    repo: REPO,
    zweig,
    aus_zweig: AUS_ZWEIG,
    lieferung_id: id,
    projekt,
    dateien,
    pr_titel: `Lieferung ${id}`,
    pr_text,
    url_ref: `https://api.github.com/repos/${REPO}/git/ref/heads/${AUS_ZWEIG}`,
    url_refs: `https://api.github.com/repos/${REPO}/git/refs`,
    url_commits: `https://api.github.com/repos/${REPO}/git/commits`,
    url_trees: `https://api.github.com/repos/${REPO}/git/trees`,
    url_pulls: `https://api.github.com/repos/${REPO}/pulls`,
  },
}];

// Hält fest, welcher Pull Request zu welcher Lieferung gehört und ob BC3 ihn zusammengeführt hat.
// Scheitert das Zusammenführen, bleibt der Pull Request offen und wird von Hand zusammengeführt.
const v = $('Lieferung ins Repo vorbereiten').first().json;
const g = $('Entscheidung auswerten').first().json;

let pr = null;
try {
  const a = $('Pull Request öffnen').first().json;
  if (a && a.number) pr = { nummer: a.number, url: a.html_url, zweig: v.zweig };
} catch (e) { pr = null; }

let gemergt = false;
let mergeFehler = null;
let commitMain = null;
try {
  const m = $input.first().json;
  gemergt = m && m.merged === true;
  // Seit 23.10.2026: der Squash-Commit auf main, nicht der Commit im Zweig (für bc3.lieferungen)
  if (gemergt && m.sha) commitMain = m.sha;
  if (!gemergt) mergeFehler = String(m?.error?.description || m?.error?.message || m?.message || 'keine Antwort').split('\n')[0].slice(0, 200);
} catch (e) { mergeFehler = 'Merge nicht gelaufen'; }
if (pr) { pr.gemergt = gemergt; pr.commit_main = commitMain; }

const befunde = !pr
  ? ['Der Pull Request konnte nicht angelegt werden. Die Dateien liegen im Zweig '
     + v.zweig + ', der Pull Request muss von Hand aufgemacht werden.']
  : gemergt
    ? [`Lieferung als Pull Request #${pr.nummer} angelegt und von BC3 gemergt: ${pr.url}`,
       'BC4 holt sie aus main.']
    : [`Lieferung liegt als Pull Request #${pr.nummer} im Repository: ${pr.url}`,
       `Automatischer Merge gescheitert (${mergeFehler}). Bitte von Hand mergen.`];

const u = g.umschlag || {};
return [{
  json: {
    ...g,
    umschlag: {
      ...u,
      lieferung: { ...(u.lieferung || {}), pr, zweig: v.zweig, repo: v.repo,
                   repo_pfade: v.dateien.map(d => d.pfad) },
      protokoll: [...(u.protokoll || []), {
        stufe: 'BC3-80 Lieferung ins Repository',
        zeitpunkt: new Date().toISOString(),
        status: pr && gemergt ? 'ok' : 'mit Fehler',
        umfang: { dateien: v.dateien.length, zweig: v.zweig },
        befunde,
      }],
    },
  },
}];

// Gibt den Umschlag an BC3-00 zurück. Im Modus test führt auch eine Freigabe hierher,
// ohne Zweig und ohne Pull Request.
const g = $('Entscheidung auswerten').first().json;
let u = g.umschlag || {};
const test = (u.lauf?.liefermodus || 'test') !== 'echt';

// Der Repo-Zweig lief nur bei Freigabe. Seit 23.10.2026 kommt von dort der ganze
// Umschlag, sonst fehlte im Protokoll der Eintrag „BC3-80 Lieferung ins Repository“
// (Lauf 2368: gescheiterter Merge stand nirgends).
let pr = null;
try {
  const v = $('Lieferung vermerken').first().json.umschlag;
  if (v) { u = v; pr = v.lieferung?.pr || null; }
} catch (e) { pr = u.lieferung?.pr || null; }
const lieferung = u.lieferung || {};

const frei = g.entscheidung === 'approved';
const ent = g.entscheidung;
const WORT = { approved: 'Freigegeben', nachbessern: 'Zur Nachbesserung zurückgegeben',
               rejected: 'Abgelehnt' };
const e = g.ereignis || {};

const neueBefunde = [
  `${WORT[ent] || 'Entschieden'} von ${e.benutzer || 'unbekannt'}`
+ `${e.am ? ' am ' + e.am : ''}.`,
  ...(e.grund ? ['Begründung: ' + e.grund] : []),
  ...(pr ? [`Lieferung liegt als Pull Request #${pr.nummer}: ${pr.url}`] : []),
  ...(frei && test ? ['Testlauf (liefermodus test): freigegeben, aber bewusst kein Zweig und kein Pull Request im Gruppen-Repository. Echt liefern: in BC3-00 "Lauf einstellen" liefermodus auf echt stellen.'] : []),
  ...(frei && !test && !pr ? ['Freigegeben, aber kein Pull Request entstanden. Siehe Protokoll davor.'] : []),
  ...(!frei ? ['Die Dateien bleiben im Lieferungsordner in _vorschau, BC4 bekommt nichts.'] : []),
];
const status = frei ? (test ? 'freigegeben (Testlauf)' : 'freigegeben') : (ent === 'nachbessern' ? 'nachbessern' : 'abgelehnt');

// Seit 23.10.2026: ein Eintrag „BC3-80 Gate 2“ statt zwei. „Entscheidung auswerten“
// legt ihn an, hier kommen Status und die Befunde zum Ausgang dazu.
const prot = [...(u.protokoll || [])];
const i = prot.map(p => p.stufe).lastIndexOf('BC3-80 Gate 2');
if (i >= 0) {
  prot[i] = { ...prot[i], status, befunde: [...(prot[i].befunde || []), ...neueBefunde] };
} else {
  prot.push({ stufe: 'BC3-80 Gate 2', zeitpunkt: new Date().toISOString(), status, befunde: neueBefunde });
}

return [{
  json: {
    lauf_id: g.lauf_id,
    umschlag: {
      ...u,
      lieferung,
      gate2: {
        entscheidung: g.entscheidung,
        liefermodus: test ? 'test' : 'echt',
        person: e.benutzer || null,
        zeitpunkt: e.am || null,
        begruendung: e.grund || null,
        pruefpunkte: e.pruefpunkte || [],
        pr,
      },
      protokoll: prot,
    },
  },
}];

/**
 * Baut den Baum fuer EINEN Commit: alle Dateien auf einmal.
 *
 * Die Git-Data-Schnittstelle nimmt den Inhalt als Klartext entgegen, base64
 * ist nur bei PUT /contents noetig. base_tree sorgt dafuer, dass alles andere
 * im Repository erhalten bleibt - ohne den Wert entstuende ein Commit, der
 * ausser unseren Dateien nichts enthaelt.
 */
const v = $('Lieferung ins Repo vorbereiten').first().json;
const basisBaum = $json.tree?.sha;

if (!basisBaum) {
  throw new Error('Der Basis-Baum von ' + v.aus_zweig + ' fehlt. Antwort: ' +
                  JSON.stringify($json).slice(0, 300));
}

return [{
  json: {
    url: v.url_trees,
    koerper: {
      base_tree: basisBaum,
      tree: v.dateien.map(d => ({
        path: d.pfad,
        mode: '100644',
        type: 'blob',
        content: d.inhalt,
      })),
    },
  },
}];

// Ein Commit mit allen Dateien, Elternteil ist die Spitze von main
const v = $('Lieferung ins Repo vorbereiten').first().json;
const eltern = $('Stand von main holen').first().json.object?.sha;
const baum = $json.sha;

if (!baum) throw new Error('Der neue Baum hat keine Kennung (BC3-80 Commit vorbereiten). Antwort: ' + JSON.stringify($json).slice(0, 300));
if (!eltern) throw new Error('Die Spitze von ' + v.aus_zweig + ' fehlt (BC3-80 Commit vorbereiten).');

const anzahl = v.dateien.length;
return [{
  json: {
    url: v.url_commits,
    koerper: {
      message: `BC3-Lieferung ${v.lieferung_id}\n\n` +
        `${anzahl} Dateien nach contracts/bc3-to-bc4/${v.projekt}/${v.lieferung_id}/.\n` +
        `Freigegeben an Gate 2, von BC3 zusammengeführt. BC4 holt aus main.`,
      tree: baum,
      parents: [eltern],
    },
  },
}];

/**
 * Den Lieferungszweig auf den neuen Commit setzen.
 *
 * Der Zweig wird erst JETZT angelegt, nicht vorher - dann gibt es ihn nur,
 * wenn auch wirklich etwas darin steht. Ein halb gefuellter Zweig ohne Commit
 * hat am 03.09. fuer Verwirrung gesorgt.
 */
const v = $('Lieferung ins Repo vorbereiten').first().json;
const commit = $json.sha;
if (!commit) throw new Error('Der Commit hat keine Kennung. Antwort: ' + JSON.stringify($json).slice(0, 300));

return [{
  json: {
    url: v.url_refs,
    koerper: { ref: `refs/heads/${v.zweig}`, sha: commit },
    commit,
  },
}];

// Zweig ließ sich nicht anlegen. 409/422 heißt: gibt es schon (erneute Freigabe nach
// Nachbesserung), dann geht es weiter. Alles andere bricht ab, ohne Pull Request.
const v = $('Lieferung ins Repo vorbereiten').first().json;
const meldung = String($json.error?.message || $json.message || '')
  .split('\n')[0].slice(0, 300);
const schonDa = /already exists|reference already exists|422|409/i.test(meldung);

if (!schonDa) {
  throw new Error(
    'Der Zweig ' + v.zweig + ' ließ sich nicht anlegen (BC3-80): ' + meldung +
    ' Es entsteht kein Pull Request. Der Commit liegt ohne Zweig im Repo und wird nicht zusammengeführt.',
  );
}

return [{ json: { ...v, zweig_bestand_schon: true,
  befund: 'Den Zweig ' + v.zweig + ' gab es bereits, der Pull Request geht trotzdem auf. '
    + 'Das ist der Normalfall bei einer erneuten Freigabe nach einer Nachbesserung.' } }];

// Eine Zeile je Gate-2-Entscheidung für die Tabelle freigaben (Supabase bc3-slicer)
const g = $input.first().json;
const e = g.ereignis || {};
const lauf = g.umschlag?.lauf?.lauf_nr || g.lauf_id;
// Werte wie in der Prüfregel der Tabelle (freigaben_entscheidung_check)
const WERT = { approved: 'freigegeben', nachbessern: 'nachbessern', rejected: 'abgelehnt' };
const entscheidung = e.frist_abgelaufen ? 'frist_abgelaufen' : WERT[g.entscheidung];
if (!entscheidung) throw new Error(`Unbekannte Entscheidung "${g.entscheidung}" (BC3-80 Freigabe-Zeile bauen)`);
if (!lauf) throw new Error('Keine Laufnummer für freigaben (BC3-80 Freigabe-Zeile bauen)');

return [{
  json: {
    lauf_id: lauf,
    zeitpunkt: e.am || new Date().toISOString(),
    entscheidung,
    person: e.benutzer || null,
    pruefpunkte: JSON.stringify(e.pruefpunkte || []),
    guete_kriterien: e.guete?.akzeptanzkriterien || null,
    guete_aufsicht: e.guete?.aufsicht || null,
    grundlage: e.grundlage || null,
    begruendung: e.grund || null,
  },
}];

// Eine Zeile je Lieferung für bc3.lieferungen (Team-Datenbank), nur Verweis auf GitHub, keine Kopien
const g = $input.first().json;
const u = g.umschlag || {};
const l = u.lieferung || {};
const z = u.gate2 || {};
const ids = u.ids || {};
const tickets = (l.dateien || []).find(d => d._datei === 'tickets') || {};

// Werte wie in der Prüfregel der Tabelle, Fristablauf zählt als Ablehnung
const STATUS = { approved: 'approved', nachbessern: 'nachbessern', rejected: 'rejected' };
const status = STATUS[z.entscheidung];

const fehlt = [];
if (!l.lieferung_id) fehlt.push('lieferung_id');
// company_id kommt aus dem Konzept von BC2, BC3 setzt sie nicht selbst
if (!ids.company_id) fehlt.push('company_id (fehlt im Konzept von BC2)');
// Seit 25.10.2026: ohne paket_id lässt sich die Lieferung in BC0 keiner Übergabe zuordnen (Simeon, ADR-003)
if (!ids.paket_id) fehlt.push('paket_id (fehlt in der Priorisierung von BC2)');
if (!l.projekt_kurzname) fehlt.push('projekt_kurzname');
if (!status) fehlt.push('gate2_status');
if (fehlt.length) throw new Error('bc3.lieferungen: es fehlt ' + fehlt.join(', ') + ' (BC3-80 Lieferungs-Zeile bauen)');

// Seit 23.10.2026: der Squash-Commit auf main, sonst der Commit im Zweig
let commit = l.pr?.commit_main || null;
if (!commit) { try { commit = $('Zweig vorbereiten').first().json.commit || null; } catch (e) { commit = null; } }

// Die Spalte nimmt einen Teilprozess (Fremdschlüssel), weitere stehen im Ticket-Set
const tp = String(ids.sub_process_id || '').split(',')[0].trim() || null;

return [{
  json: {
    werte: [
      l.lieferung_id,
      ids.company_id,
      ids.process_id || u.konzept?.kp_id || null,
      tp,
      l.projekt_kurzname,
      tickets.schema_version || null,
      `contracts/bc3-to-bc4/${l.projekt_kurzname}/${l.lieferung_id}/`,
      commit,
      status,
      z.person || null,
      z.zeitpunkt || new Date().toISOString(),
      JSON.stringify(z.pruefpunkte || []),
      z.begruendung || null,
      ids.paket_id,
      ids.anfrage_id || null,
    ],
    // anfrage_id ist ohne Anfrage (Portfolio) leer, das kommt als Hinweis ins Protokoll
    ohne_anfrage: !ids.anfrage_id,
  },
}];

// BC3-00 bekommt den Umschlag aus "Gate 2 abschliessen", egal ob in bc3.lieferungen geschrieben wurde
const g = $('Gate 2 abschliessen').first().json;
let befund = null;
try {
  // Seit 23.10.2026: scheitert schon die Zeile (z. B. company_id fehlt), steht deren Grund im Befund,
  // nicht der Folgefehler der Datenbank
  const zeile = $('Lieferungs-Zeile bauen').isExecuted ? $('Lieferungs-Zeile bauen').first().json : null;
  if (zeile?.error) {
    befund = 'bc3.lieferungen nicht geschrieben: ' + String(zeile.error.message || 'ohne Angabe').split('\n')[0].slice(0, 200);
  } else if ($('In bc3.lieferungen schreiben').isExecuted) {
    const r = $('In bc3.lieferungen schreiben').first().json;
    befund = r.lieferung_id
      ? 'In bc3.lieferungen eingetragen: ' + r.lieferung_id + ' (' + r.gate2_status + ')'
        + (zeile?.ohne_anfrage ? ', ohne anfrage_id (von BC2 nicht geliefert)' : '')
      : 'bc3.lieferungen nicht geschrieben: ' + String(r.error?.message || r.message || 'ohne Angabe').split('\n')[0].slice(0, 200);
  }
} catch (e) { befund = null; }
if (!befund) return [{ json: g }];

const u = g.umschlag || {};
const prot = [...(u.protokoll || [])];
// An den Eintrag „BC3-80 Gate 2“ hängen, nicht an den letzten Eintrag
let i = prot.map(p => p.stufe).lastIndexOf('BC3-80 Gate 2');
if (i < 0) i = prot.length - 1;
if (i >= 0) prot[i] = { ...prot[i], befunde: [...(prot[i].befunde || []), befund] };
return [{ json: { ...g, umschlag: { ...u, protokoll: prot } } }];
